    /// <summary>
    /// 程式化生成 800 × 600 科技感幾何網格與準心圖樣 (WriteableBitmap)。
    /// </summary>
    private static WriteableBitmap GenerateTechGridBitmap(int width, int height)
    {
        var wb = new WriteableBitmap(
            new PixelSize(width, height),
            new Avalonia.Vector(96, 96),
            PixelFormat.Bgra8888,
            AlphaFormat.Premul);

        using var fb = wb.Lock();
        unsafe
        {
            byte* basePtr = (byte*)fb.Address;
            int stride = fb.RowBytes;
            int cx = width / 2;
            int cy = height / 2;

            for (int y = 0; y < height; y++)
            {
                uint* row = (uint*)(basePtr + y * stride);
                double dy = y - cy;
                double ny = (double)y / height;

                for (int x = 0; x < width; x++)
                {
                    double dx = x - cx;
                    double nx = (double)x / width;
                    double dist = Math.Sqrt(dx * dx + dy * dy);

                    // 1. 深色幾何漸層底色 (Deep Blue-Purple Tech Gradient: #0A0D1E -> #1E1B4B)
                    double grad = (nx * 0.5 + ny * 0.5);
                    int r = (int)(10 + 20 * grad);
                    int g = (int)(13 + 15 * (1 - nx));
                    int b = (int)(32 + 55 * ny);

                    // 2. 科技次網格 (Minor grid 16px) 與主網格 (Major grid 64px)
                    bool isMinorGrid = (x % 16 == 0) || (y % 16 == 0);
                    bool isMajorGrid = (x % 64 == 0) || (y % 64 == 0);

                    if (isMinorGrid)
                    {
                        r = Math.Min(255, r + 16);
                        g = Math.Min(255, g + 28);
                        b = Math.Min(255, b + 55);
                    }

                    if (isMajorGrid)
                    {
                        r = Math.Min(255, r + 45);
                        g = Math.Min(255, g + 90);
                        b = Math.Min(255, b + 150);
                    }

                    // 3. 菱形幾何導引框 (Diamond coordinate frame)
                    double manhattan = Math.Abs(dx) + Math.Abs(dy);
                    if (Math.Abs(manhattan - 160) < 2.0 || Math.Abs(manhattan - 240) < 2.0)
                    {
                        r = Math.Min(255, r + 130);
                        g = Math.Min(255, g + 85);
                        b = 255;
                    }

                    // 4. 同心校準圓環 (Concentric Reticles at center: radius 80, 140, 200)
                    if (Math.Abs(dist - 80) < 1.8 || Math.Abs(dist - 140) < 1.8 || Math.Abs(dist - 200) < 1.8)
                    {
                        r = 50;
                        g = Math.Min(255, g + 190);
                        b = 255;
                    }

                    // 5. 十字準心 (Crosshair axes through center)
                    if ((Math.Abs(dx) < 1.0 && Math.Abs(dy) < 240) || (Math.Abs(dy) < 1.0 && Math.Abs(dx) < 240))
                    {
                        r = 100;
                        g = 220;
                        b = 255;
                    }

                    // 6. 核心發光點 (Center luminous glow)
                    if (dist < 40)
                    {
                        double glow = (1.0 - dist / 40.0);
                        r = Math.Min(255, (int)(r + 140 * glow));
                        g = Math.Min(255, (int)(g + 180 * glow));
                        b = Math.Min(255, (int)(b + 255 * glow));
                    }

                    // 7. 外邊框科技定位角標 (Corner registration brackets)
                    if ((x < 30 || x >= width - 30) && (y < 30 || y >= height - 30))
                    {
                        if (x == 10 || x == width - 11 || y == 10 || y == height - 11)
                        {
                            r = 129; g = 140; b = 248; // Indigo accent
                        }
                    }

                    // BGRA8888 格式寫入 (Little Endian: B, G, R, A)
                    row[x] = (uint)((255 << 24) | ((byte)r << 16) | ((byte)g << 8) | (byte)b);
                }
            }
        }

        return wb;
    }

    /// <summary>
    /// 程式化生成 1024 × 768 同心光環光譜與放射光束圖樣 (WriteableBitmap)。
    /// </summary>
    private static WriteableBitmap GenerateConcentricRingsBitmap(int width, int height)
    {
        var wb = new WriteableBitmap(
            new PixelSize(width, height),
            new Avalonia.Vector(96, 96),
            PixelFormat.Bgra8888,
            AlphaFormat.Premul);

        using var fb = wb.Lock();
        unsafe
        {
            byte* basePtr = (byte*)fb.Address;
            int stride = fb.RowBytes;
            int cx = width / 2;
            int cy = height / 2;
            double maxDist = Math.Sqrt(cx * cx + cy * cy);

            for (int y = 0; y < height; y++)
            {
                uint* row = (uint*)(basePtr + y * stride);
                double dy = y - cy;

                for (int x = 0; x < width; x++)
                {
                    double dx = x - cx;
                    double dist = Math.Sqrt(dx * dx + dy * dy);
                    double angle = Math.Atan2(dy, dx); // -PI ~ PI

                    // 1. 同心光環波形 (High-frequency concentric rings)
                    double wave = Math.Sin(dist * 0.08); // -1 ~ 1
                    double waveSharp = Math.Pow(0.5 + 0.5 * wave, 3.0); // 銳利聚焦環

                    // 2. 角度彩虹色相環 (Hue cycle based on angle and radius: 0 ~ 1)
                    double hue = (angle + Math.PI) / (2.0 * Math.PI) + (dist / maxDist) * 0.5;
                    hue -= Math.Floor(hue);

                    // HSV 轉 RGB
                    ColorFromHsv(hue, 0.85, 0.25 + 0.75 * waveSharp, out int r, out int g, out int b);

                    // 3. 放射狀光芒 (Radial light spokes, 16 beams)
                    double spokes = Math.Pow(0.5 + 0.5 * Math.Cos(angle * 16), 4.0);
                    r = Math.Min(255, (int)(r + 45 * spokes));
                    g = Math.Min(255, (int)(g + 45 * spokes));
                    b = Math.Min(255, (int)(b + 45 * spokes));

                    // 4. 核心高光核心 (Central intense core)
                    if (dist < 60)
                    {
                        double core = Math.Pow(1.0 - dist / 60.0, 2.0);
                        r = Math.Min(255, (int)(r + 255 * core));
                        g = Math.Min(255, (int)(g + 245 * core));
                        b = Math.Min(255, (int)(b + 230 * core));
                    }

                    // 5. 漸暈暗角 (Vignette toward corners)
                    double vignette = 1.0 - Math.Clamp(dist / maxDist, 0.0, 1.0);
                    r = (int)(r * (0.45 + 0.55 * vignette));
                    g = (int)(g * (0.45 + 0.55 * vignette));
                    b = (int)(b * (0.45 + 0.55 * vignette));

                    // BGRA8888 格式寫入
                    row[x] = (uint)((255 << 24) | ((byte)r << 16) | ((byte)g << 8) | (byte)b);
                }
            }
        }

        return wb;
    }

    /// <summary>
    /// HSV 色彩空間轉換至 RGB。
    /// </summary>
    private static void ColorFromHsv(double h, double s, double v, out int r, out int g, out int b)
    {
        double c = v * s;
        double x = c * (1 - Math.Abs((h * 6) % 2 - 1));
        double m = v - c;

        double r1, g1, b1;
        int sector = (int)(h * 6) % 6;
        switch (sector)
        {
            case 0: r1 = c; g1 = x; b1 = 0; break;
            case 1: r1 = x; g1 = c; b1 = 0; break;
            case 2: r1 = 0; g1 = c; b1 = x; break;
            case 3: r1 = 0; g1 = x; b1 = c; break;
            case 4: r1 = x; g1 = 0; b1 = c; break;
            default: r1 = c; g1 = 0; b1 = x; break;
        }

        r = (int)Math.Clamp((r1 + m) * 255, 0, 255);
        g = (int)Math.Clamp((g1 + m) * 255, 0, 255);
        b = (int)Math.Clamp((b1 + m) * 255, 0, 255);
    }
